  windowPair(g, { x: 69, y: 2, z: 21, face: "south" });
  windowPair(g, { x: 74, y: 2, z: 21, face: "south" });
  windowPair(g, { x: 69, y: 6, z: 21, face: "south" });
  windowPair(g, { x: 74, y: 6, z: 21, face: "south" });
